// Code Node - Split Items into Separate Rows
const items = $json.data;

return items.map(item => ({
  json: item
}));

const apiItems = $input.all();
const results = [];

for (const apiItem of apiItems) {
  const itemData = apiItem.json;

  results.push({
    json: {
      adminData: itemData.adminData || {},
      domainInfo: itemData.domainInfo || {},
      contactEmail: itemData.contactEmail || '',
      submissionMethod: itemData.submissionMethod || '',
      domain: itemData.domainInfo?.Domain || '',
      status: 'matched'
    }
  });
}

return results;

const snapshotData = $input.item.json;

// Recover adminData and domainInfo from Code in JavaScript1 (lost when HTTP Request1 replaced $json)
const code1Items = $('Code in JavaScript1').all();
const code1Item = code1Items[$itemIndex];
const adminData = code1Item?.json?.adminData || {};
const domainInfo = code1Item?.json?.domainInfo || {};

// --- TEMPLATE SELECTION ---
const subjectSnapshot = snapshotData.subjectSnapshot || {};
const addresses = snapshotData.addressSnapshots || [];
const principalAddress = addresses.find(addr => addr.metadata && addr.metadata.principal) || addresses[0] || {};
const state = (principalAddress.state || '').toLowerCase().trim();
const country = (principalAddress.country || '').toLowerCase().trim();

const privacyStates = {
  'california': 'California', 'ca': 'California',
  'colorado': 'Colorado', 'co': 'Colorado',
  'utah': 'Utah', 'ut': 'Utah',
  'virginia': 'Virginia', 'va': 'Virginia',
  'connecticut': 'Connecticut', 'ct': 'Connecticut',
