  'texas': 'Texas', 'tx': 'Texas',
  'new jersey': 'New Jersey', 'newjersey': 'New Jersey', 'nj': 'New Jersey',
  'new hampshire': 'New Hampshire', 'newhampshire': 'New Hampshire', 'nh': 'New Hampshire',
