  'at', 'be', 'bg', 'hr', 'cy', 'cz', 'dk', 'ee', 'fi', 'fr', 'de', 'gr', 'hu',
  'ie', 'it', 'lv', 'lt', 'lu', 'mt', 'nl', 'pl', 'pt', 'ro', 'sk', 'si', 'es',
  'se', 'ch', 'gb', 'no', 'is', 'li'];

let templateRegion = 'California';
if (country === 'canada' || country === 'ca') {
  templateRegion = privacyStates[state] || 'Canada';
} else if (euCountries.includes(country)) {
  templateRegion = 'EU';
} else if (country === 'us' || country === 'usa' || country === 'united states') {
  templateRegion = privacyStates[state] || 'California';
}

const templateRow = $('Get row(s) in sheet1').first().json;
const template = templateRow[templateRegion] || templateRow['California'] || 'Template not found';

