const currentDomain = (domainInfo['Domain'] || adminData.url || '').toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0]
  .split('?')[0]
  .trim();

const useFullAddress = fullAddressDomains.includes(currentDomain);

// --- TEMPLATE FILLING ---
const fullName = `${subjectSnapshot.firstName || ''} ${subjectSnapshot.lastName || ''}`.trim();

let formattedAddress = '';
if (addresses && addresses.length > 0) {
  if (useFullAddress) {
    formattedAddress = addresses.map(addr => {
      return [addr.address || '', addr.address2 || '', addr.city || '',
        addr.state || '', addr.zipCode || '', addr.country || ''
      ].filter(part => part !== '').join(', ');
    }).join('\n');
  } else {
    const uniquePartialAddresses = new Set();
    addresses.forEach(addr => {
      const countryRaw = (addr.country || principalAddress.country || '').toString().trim().toLowerCase();
      const isUS = ['us', 'usa', 'united states', 'united states of america'].includes(countryRaw);
      const city = addr.city || '';
      const st = addr.state || '';
      const ctry = addr.country || principalAddress.country || '';
      const partialAddress = isUS
        ? [city, st].filter(p => p !== '').join(', ')
        : [city, ctry].filter(p => p !== '').join(', ');
      if (partialAddress) uniquePartialAddresses.add(partialAddress);
    });
    formattedAddress = Array.from(uniquePartialAddresses).join('\n');
  }
} else {
  const countryRaw = (principalAddress.country || '').toString().trim().toLowerCase();
  const isUS = ['us', 'usa', 'united states', 'united states of america'].includes(countryRaw);
  const addressParts = useFullAddress
    ? [principalAddress.address || '', principalAddress.address2 || '', principalAddress.city || '', principalAddress.state || '', principalAddress.zipCode || '', principalAddress.country || ''].filter(p => p !== '')
    : isUS
      ? [principalAddress.city || '', principalAddress.state || ''].filter(p => p !== '')
      : [principalAddress.city || '', principalAddress.country || ''].filter(p => p !== '');
  formattedAddress = addressParts.join(', ');
}

const url = adminData.url || '';
const recipientEmail = domainInfo['Email/Form for submission'] || '';

let filledTemplate = template;
filledTemplate = filledTemplate
  .replace(/Full name\s*-\s*[\n\r]*/g, `Full name - ${fullName}\n\n`)
  .replace(/Home address\s*-\s*[\n\r]*/g, `Home address - ${formattedAddress}\n\n`)
  .replace(/this URL \(\)/g, `this URL (${url})`)
  .replace(/accessible via this URL \(\)/g, `accessible via this URL (${url})`);

return {
  json: {
    ...snapshotData,
    adminData: adminData,
    domainInfo: domainInfo,
    templateRegion: templateRegion,
    emailTemplate: template,
    filledEmailTemplate: filledTemplate,
    filledEmailTemplateHtml: filledTemplate.replace(/\n/g, '<br>'),
    recipientEmail: recipientEmail,
    fullName: fullName,
    fullAddress: formattedAddress,
    url: url,
    detectedState: state.toUpperCase(),
    detectedCountry: country.toUpperCase()
  }
};

// Get data from current node (already has all data from If1)
const data = $input.item.json;
const binary = $input.item.binary;
const template = data.emailTemplate;

// Admin data and domain info
const adminData = data.adminData || {};
const domainInfo = data.domainInfo || {};

// NEW: Snapshot-based structure
const subjectSnapshot = data.subjectSnapshot || {};
const addresses = data.addressSnapshots || [];
const principalAddress = addresses.find(addr => addr.metadata && addr.metadata.principal) || addresses[0] || {};

// URL
const url = adminData.url || data.url || '';

// Build full name
const fullName = `${subjectSnapshot.firstName || ''} ${subjectSnapshot.lastName || ''}`.trim();

// --- FULL ADDRESS DOMAIN LIST ---
const fullAddressDomains = [
  'checkr.com',
  'rocketreach.co',
  'peekyou.com',
  'checkpeople.com',
  'homes.com',
  'zoominfo.com',
  'radaris.com',
