  'colorado.ourstates.org',
  'connecticut.ourstates.org',
  'michigan.ourstates.org',
  'maryland.ourstates.org',
  'massachusetts.ourstates.org',
  'missouri.ourstates.org',
  'florida.ourstates.org',
  'california.ourstates.org',
  'arizona.ourstates.org',
  'alabama.ourstates.org',
  'wisconsin.ourstates.org',
