  'cocofinder.com',
  'mylife.com',
  'reunion.com',
  'thread.for.more.information.com',
  'secure.information.com',
];

// Address logic - use domain list instead of deprecated 'Info shared' spreadsheet field
const currentDomain = (domainInfo['Domain'] || adminData.url || data.url || '').toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0]
  .split('?')[0]
  .trim();

const useFullAddress = fullAddressDomains.includes(currentDomain);

let formattedAddress = '';

if (addresses && addresses.length > 0) {
  if (useFullAddress) {
    formattedAddress = addresses.map(addr => {
      return [
        addr.address || '',
        addr.address2 || '',
        addr.city || '',
        addr.state || '',
        addr.zipCode || '',
        addr.country || ''
      ].filter(part => part !== '').join(', ');
    }).join('\n');
  } else {
    const uniquePartialAddresses = new Set();
    addresses.forEach(addr => {
      const countryRaw = (addr.country || principalAddress.country || '').toString().trim().toLowerCase();
      const isUS = ['us', 'usa', 'united states', 'united states of america'].includes(countryRaw);
      const city = addr.city || '';
      const state = addr.state || '';
      const country = addr.country || principalAddress.country || '';
      const partialAddress = isUS
        ? [city, state].filter(p => p !== '').join(', ')
        : [city, country].filter(p => p !== '').join(', ');
      if (partialAddress) uniquePartialAddresses.add(partialAddress);
    });
    formattedAddress = Array.from(uniquePartialAddresses).join('\n');
  }
} else {
  formattedAddress = 'No address available';
}

const recipientEmail = domainInfo['Email/Form for submission'] || '';

// Generate unique ID
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const hashSource = `${Date.now()}${$itemIndex}${Math.random()}${Math.random()}`;
let hash = 0;
for (let i = 0; i < hashSource.length; i++) {
  hash = ((hash << 5) - hash) + hashSource.charCodeAt(i);
  hash = hash & hash;
}
hash = Math.abs(hash);
let uniqueId = 'ID-';
for (let i = 0; i < 7; i++) {
  uniqueId += chars[Math.floor((hash / Math.pow(10, i)) % chars.length)];
}

