  .replace(/Home address\s*-\s*\n/g, `Home address - \n${formattedAddress}\n\n`)
  .replace(/this URL \(\)/g, `this URL (${url})`)
  .replace(/accessible via this URL \(\)/g, `accessible via this URL (${url})`);

return {
