    ...data,
    generatedId: uniqueId,
    generatedAt: new Date().toISOString(),
    filledEmailTemplate: filledTemplate,
    filledEmailTemplateHtml: filledTemplate.replace(/\n/g, '<br>'),
    recipientEmail: recipientEmail,
    fullName: fullName,
    fullAddress: formattedAddress,
    url: url
  },
  binary: binary
};

const staticData = $getWorkflowStaticData('global');
const batchCount = $input.all().length;
staticData.emailsSent = (staticData.emailsSent || 0) + batchCount;
const totalSent = staticData.emailsSent;

const currentPage = $node["Merge Pagination Data"].json.currentPage || 1;
const maxPages = parseInt($node["Merge Pagination Data"].json.maxPages) || 20;

if (totalSent >= 200 || currentPage >= maxPages) {
  return [{
    json: {
      stopProcessing: true,
      totalEmailsSent: totalSent,
      message: totalSent >= 200 
        ? `Reached email limit: ${totalSent} emails sent` 
        : `Checked ${maxPages} pages, sent ${totalSent} emails total`
    }
  }];
}

return [{
  json: {
    currentPage: currentPage,
    nextPage: currentPage + 1,
    maxPages: maxPages,
    emailsSent: totalSent,
    stopProcessing: false,
    message: `Sent ${batchCount} this batch (${totalSent} total), continuing to next page`
  }
}];

// Extract contact information from exposure source API response
const exposureSource = $input.item.json;

// Recover original admin data (lost after Fetch Exposure Source Details replaced $json)
const adminItem = $('Code in JavaScript').all()[$itemIndex];
const adminData = adminItem ? adminItem.json : {};

// Check if manual handling is required
const manualHandlingRequired = exposureSource.manualHandlingRequired || false;

if (manualHandlingRequired) {
  return {
    json: {
      ...($input.item.json),
      adminData: adminData,
      domainInfo: null,
      contactEmail: null,
      submissionMethod: null,
      submissionUrl: null,
      manualHandlingRequired: true,
      skipped: true,
      skipReason: "Manual handling required for this exposure source"
    }
  };
}

const email = exposureSource.email || '';
const formUrl = exposureSource.formUrl || '';

if (!email && formUrl) {
  return {
    json: {
      ...($input.item.json),
      adminData: adminData,
      domainInfo: null,
      contactEmail: null,
      submissionMethod: null,
      submissionUrl: null,
      skipped: true,
      skipReason: "Only form submission available, no email contact"
    }
  };
}

if (!email) {
  return {
    json: {
      ...($input.item.json),
      adminData: adminData,
      domainInfo: null,
      contactEmail: null,
      submissionMethod: null,
      submissionUrl: null,
      skipped: true,
      skipReason: "No email or form contact available"
    }
  };
}

const submissionMethod = email ? 'email' : 'form';
const submissionUrl = email ? '' : formUrl;

const domainInfo = {
  'Domain': exposureSource.domain || exposureSource.title || '',
  'Contact Email': email,
  'Email/Form for submission': email,
  'Submission Method': submissionMethod,
  'Submission URL': submissionUrl,
  'Info shared': exposureSource.infoShared || ''
};

return {
  json: {
    ...($input.item.json),
    adminData: adminData,
    domainInfo: domainInfo,
    contactEmail: email,
    submissionMethod: submissionMethod,
    submissionUrl: submissionUrl,
    manualHandlingRequired: false,
    skipped: false
  }
};

const staticData = $getWorkflowStaticData('global');
const totalSent = staticData.emailsSent || 0;

const currentPage = $node["Merge Pagination Data"].json.currentPage || 1;
const maxPages = parseInt($node["Merge Pagination Data"].json.maxPages) || 20;

if (totalSent >= 200) {
  return [{
    json: {
      stopProcessing: true,
      totalEmailsSent: totalSent,
      message: `Reached email limit: ${totalSent} emails sent`
    }
  }];
}

if (currentPage < maxPages) {
  return [{
    json: {
      currentPage: currentPage,
      nextPage: currentPage + 1,
      maxPages: maxPages,
      emailsSent: totalSent,
      stopProcessing: false,
      message: `All items skipped on page ${currentPage}, moving to next page`
    }
  }];
} else {
  return [{
    json: {
      stopProcessing: true,
      totalEmailsSent: totalSent,
      message: `All pages checked, sent ${totalSent} emails total`
    }
  }];
}
